<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {Line,Doughnut,Bar} from 'vue-chartjs';
import {Chart as C,CategoryScale,LinearScale,PointElement,LineElement,BarElement,ArcElement,Tooltip,Legend,Filler} from 'chart.js';
import {state} from '../store';
import {wrapChartLabel,chartLabelWidth} from '../chart-labels';
C.register(CategoryScale,LinearScale,PointElement,LineElement,BarElement,ArcElement,Tooltip,Legend,Filler);
const p=defineProps({trend:{default:()=>[]},scores:{default:()=>[]},distribution:{default:()=>[]}});
const fontsReady=ref(false),barContainer=ref(null),barWidth=ref(288);let barObserver,mounted=false,measureCanvas;
onMounted(async()=>{mounted=true;if(document.fonts)await document.fonts.ready;if(mounted)fontsReady.value=true});
watch(barContainer,element=>{barObserver?.disconnect();if(!element)return;barWidth.value=element.clientWidth;barObserver=new ResizeObserver(entries=>barWidth.value=Math.round(entries[0].contentRect.width));barObserver.observe(element)},{flush:'post'});
onBeforeUnmount(()=>{mounted=false;barObserver?.disconnect()});
const tokens=computed(()=>{state.dark;state.textSize;const style=getComputedStyle(document.documentElement);return {font:Math.max(16,parseFloat(style.fontSize)||16),text:style.getPropertyValue('--muted').trim()||'#B5C9BE',grid:style.getPropertyValue('--border').trim()||'#35574A',accent:style.getPropertyValue('--color-accent').trim()||'#BEF78F',soft:style.getPropertyValue('--blue-soft').trim()||'rgba(190,247,143,.12)'}});
const font=computed(()=>({size:tokens.value.font,family:'Plus Jakarta Sans, Segoe UI, sans-serif'}));
const isId=computed(()=>state.language==='id');
// Shared tooltips stay inside their canvas; the values below also work on touch and keyboard.
const options=computed(()=>({responsive:true,maintainAspectRatio:false,animation:matchMedia('(prefers-reduced-motion: reduce)').matches?false:undefined,layout:{padding:8},plugins:{legend:{display:false},tooltip:{titleFont:font.value,bodyFont:font.value,padding:12,callbacks:{title:items=>wrapLabel(items[0]?.label,22)}}},scales:{x:{grid:{display:false},ticks:{color:tokens.value.text,font:font.value,maxRotation:0,autoSkip:true,maxTicksLimit:6}},y:{beginAtZero:true,ticks:{precision:0,color:tokens.value.text,font:font.value,maxTicksLimit:5},grid:{color:tokens.value.grid}}}}));
const trendData=computed(()=>({labels:p.trend.map(x=>x.month),datasets:[{label:isId.value?'Ujian':'Assessments',data:p.trend.map(x=>x.attempts),borderColor:tokens.value.accent,backgroundColor:tokens.value.soft,fill:true,tension:.35,borderWidth:3,pointRadius:4,pointHitRadius:16}]}));
const palette=['#BEF78F','#A9D99D','#5F9A7B','#4ADE80','#6FC2AA','#D4E7AF','#8EA98D'];
function wrapLabel(value,limit=22){return wrapChartLabel(value,limit,text=>[...text].length)}
const barLabels=computed(()=>{measureCanvas=measureCanvas||document.createElement('canvas');const context=measureCanvas.getContext('2d');context.font=font.value.size+'px '+font.value.family;return p.scores.map(score=>wrapChartLabel(scoreName(score),chartLabelWidth(barWidth.value),text=>context.measureText(text).width))});
const scoreName=x=>isId.value?(x.name||x.code):(x.name_en||x.name||x.code);
const bars=computed(()=>({labels:barLabels.value,datasets:[{label:'%',data:p.scores.map(x=>x.normalized_score??x.score),backgroundColor:tokens.value.accent,borderRadius:6,maxBarThickness:28}]}));
const barOptions=computed(()=>({...options.value,indexAxis:'y',layout:{padding:{left:16,right:12,top:16,bottom:8}},scales:{x:{min:0,max:100,grid:{color:tokens.value.grid},ticks:{color:tokens.value.text,font:font.value,maxTicksLimit:3}},y:{grid:{display:false},ticks:{color:tokens.value.text,font:font.value,autoSkip:false,padding:10}}}}));
const barHeight=computed(()=>Math.max(336,barLabels.value.reduce((sum,lines)=>sum+Math.max(72,lines.length*tokens.value.font*1.5+24),64))+'px');
const donut=computed(()=>({labels:p.distribution.map(x=>x.level||'—'),datasets:[{data:p.distribution.map(x=>x.count),backgroundColor:palette,borderColor:tokens.value.grid,borderWidth:1}]}));
const donutOptions=computed(()=>({...options.value,cutout:'72%',scales:{}}));
const total=computed(()=>p.distribution.reduce((sum,x)=>sum+Number(x.count),0));
</script>
<template>
<section class="analytics-grid">
    <article class="panel"><div class="panel-heading"><div><h3>{{isId?'Aktivitas asesmen':'Assessment activity'}}</h3><p>{{isId?'Ujian dimulai setiap bulan.':'Assessments started each month.'}}</p></div><span class="badge blue">{{isId?'Data aktual':'Live data'}}</span></div><div v-if="trend.length&&fontsReady" class="chart-wrap analytics-chart"><Line :data="trendData" :options="options" role="img" :aria-label="isId?'Grafik aktivitas asesmen; nilai tersedia di bawah.':'Assessment activity chart; values are available below.'"/></div><p v-else-if="!trend.length" class="analytics-empty">{{isId?'Belum ada aktivitas asesmen dalam periode ini.':'No assessment activity in this period yet.'}}</p><details v-if="trend.length" class="analytics-values"><summary>{{isId?'Lihat jumlah ujian bulanan':'View monthly assessment counts'}}</summary><dl><div v-for="(row,i) in trend" :key="i"><dt>{{row.month}}</dt><dd>{{row.attempts}}</dd></div></dl></details></article>
    <article class="panel"><div class="panel-heading"><div><h3>{{isId?'Distribusi kemahiran':'Proficiency distribution'}}</h3><p>{{isId?'Klasifikasi internal dari hasil final.':'Internal classifications from final results.'}}</p></div></div><template v-if="total"><div v-if="fontsReady" class="chart-wrap analytics-chart analytics-donut"><Doughnut :data="donut" :options="donutOptions" role="img" :aria-label="isId?'Grafik distribusi kemahiran; jumlah setiap level tersedia di bawah.':'Proficiency distribution chart; counts by level are available below.'"/></div><ul class="distribution-legend"><li v-for="(row,i) in distribution" :key="i"><i :style="{background:palette[i%palette.length]}" aria-hidden="true"></i><span>{{row.level||'—'}}</span><strong>{{row.count}}</strong></li></ul></template><div v-else class="analytics-empty"><span class="empty-ring" aria-hidden="true"></span><p>{{isId?'Distribusi tersedia setelah ujian selesai dinilai.':'Distribution appears after assessments are fully graded.'}}</p></div></article>
</section>
<section v-if="scores.length" class="panel analytics-competencies"><div class="panel-heading"><div><h3>{{isId?'Penguasaan per kompetensi':'Competency performance'}}</h3><p>{{isId?'Rata-rata persentase dari hasil final terpilih.':'Average percentages from selected final results.'}}</p></div></div><div v-if="fontsReady" ref="barContainer" class="chart-wrap analytics-chart analytics-bars" :style="{height:barHeight}"><Bar :data="bars" :options="barOptions" role="img" :aria-label="isId?'Grafik penguasaan kompetensi; nilai tersedia di bawah.':'Competency performance chart; values are available below.'"/></div><details class="analytics-values"><summary>{{isId?'Lihat nilai kompetensi':'View competency values'}}</summary><dl><div v-for="(row,i) in scores" :key="row.competency_id||i"><dt>{{scoreName(row)}}</dt><dd>{{row.normalized_score??row.score}}%</dd></div></dl></details></section>
</template>
<style scoped>
.analytics-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:1.5rem;margin:1.5rem 0;align-items:stretch}.analytics-grid>.panel,.analytics-competencies{min-width:0;padding:1.5rem}.analytics-grid .panel-heading,.analytics-competencies .panel-heading{padding:0;margin-bottom:1.5rem;gap:1rem}.analytics-grid .analytics-chart,.analytics-competencies .analytics-chart{height:22rem;position:relative;min-width:0;max-width:100%;padding:0}.analytics-chart canvas{max-width:100%}.analytics-grid .analytics-donut{height:19rem}.analytics-empty{min-height:20rem;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:1.25rem;text-align:center;color:var(--muted);font-size:1.125rem;line-height:1.7;max-width:24rem;margin:auto}.empty-ring{height:6rem;width:6rem;border:1rem solid var(--border);border-radius:50%}.analytics-competencies{margin-bottom:1.5rem}.distribution-legend{list-style:none;padding:1rem 0 0;margin:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,10rem),1fr));gap:.75rem 1.5rem}.distribution-legend li{display:flex;align-items:center;gap:.75rem;font-size:1.0625rem;line-height:1.5;min-width:0}.distribution-legend i{width:.875rem;height:.875rem;border-radius:50%;flex-shrink:0}.distribution-legend span{overflow-wrap:anywhere}.distribution-legend strong{margin-left:auto;font-variant-numeric:tabular-nums}.analytics-values{margin-top:1rem;border-top:1px solid var(--border)}.analytics-values summary{font-size:1.0625rem;font-weight:600;padding:.75rem 0;cursor:pointer;color:var(--text)}.analytics-values dl{margin:0}.analytics-values dl>div{display:flex;align-items:baseline;justify-content:space-between;gap:1rem;padding:.75rem 0;border-top:1px solid var(--border);font-size:1.0625rem;line-height:1.6}.analytics-values dt{min-width:0;overflow-wrap:anywhere}.analytics-values dd{margin:0;font-weight:700;flex-shrink:0;font-variant-numeric:tabular-nums}@media(max-width:1100px){.analytics-grid{grid-template-columns:1fr}}@media(max-width:600px){.analytics-grid>.panel,.analytics-competencies{padding:1rem}.analytics-grid .analytics-chart,.analytics-competencies .analytics-chart{height:21rem}.analytics-grid .analytics-donut{height:18rem}}
</style>
